INSERT INTO `ld_skill` VALUES (1,'Project Management','Planning, executing, and closing projects effectively. Covers methodologies like Agile, Scrum, and Waterfall, along with tools for task tracking, resource allocation, and stakeholder communication.','2026-08-20 17:14:46',0,'active','2026-08-20 17:14:46'),(2,'Leadership','Inspiring and guiding teams toward achieving organizational goals. Includes decision-making, conflict resolution, motivation strategies, and building high-performance teams.','2026-08-20 17:14:46',0,'active','2026-08-20 17:14:46'),(3,'Communication Skills','Effective verbal, written, and interpersonal communication. Covers presentation techniques, active listening, professional email writing, and cross-cultural communication.','2026-08-20 17:14:46',0,'active','2026-08-20 17:14:46'),(4,'Technical Writing','Creating clear, concise, and user-friendly documentation. Includes writing manuals, guides, SOPs, API docs, and knowledge base articles for technical and non-technical audiences.','2026-08-20 17:14:46',0,'active','2026-08-20 17:14:46'),(5,'Data Analysis','Collecting, processing, and interpreting data to drive informed decisions. Covers Excel, SQL, data visualization tools, statistical methods, and reporting frameworks.','2026-08-20 17:14:46',0,'active','2026-08-20 17:14:46'),(6,'Cybersecurity','Protecting systems, networks, and data from digital attacks. Covers threat assessment, vulnerability management, encryption, access controls, and incident response.','2026-08-20 17:14:46',0,'active','2026-08-20 17:14:46'),(7,'Web Development','Building and maintaining websites and web applications. Covers HTML, CSS, JavaScript, front-end frameworks, back-end development, and responsive design principles.','2026-08-20 17:14:46',0,'active','2026-08-20 17:14:46'),(8,'Customer Service','Delivering excellent support and building customer loyalty. Covers conflict resolution, empathy, problem-solving, CRM tools, and service recovery strategies.','2026-08-20 17:14:46',0,'active','2026-08-20 17:14:46'),(9,'Time Management','Prioritizing tasks and managing workload efficiently. Covers planning techniques, delegation, avoiding procrastination, and using productivity tools to meet deadlines.','2026-08-20 17:14:46',0,'active','2026-08-20 17:14:46'),(10,'Critical Thinking','Analyzing situations objectively and making reasoned judgments. Covers logical reasoning, identifying biases, evaluating evidence, and creative problem-solving approaches.','2026-08-20 17:14:46',0,'active','2026-08-20 17:14:46'),(11,'Financial Literacy','Understanding financial concepts, budgeting, and accounting principles. Covers reading financial statements, managing budgets, cost-benefit analysis, and investment basics.','2026-08-20 17:14:46',0,'active','2026-08-20 17:14:46'),(12,'Teamwork & Collaboration','Working effectively within a team to achieve shared objectives. Covers collaboration tools, group dynamics, cross-functional teamwork, and building trust.','2026-08-20 17:14:46',0,'active','2026-08-20 17:14:46'),(13,'Adaptability','Adjusting to changing environments and new challenges. Covers resilience, continuous learning mindset, flexibility in approaches, and embracing innovation.','2026-08-20 17:14:46',0,'active','2026-08-20 17:14:46'),(14,'Quality Assurance','Ensuring products and services meet defined standards. Covers testing methodologies, process improvement, compliance auditing, and continuous quality frameworks.','2026-08-20 17:14:46',0,'active','2026-08-20 17:14:46'),(15,'Human Resources Management','Managing the employee lifecycle from recruitment to retirement. Covers talent acquisition, performance evaluation, compensation, training, and employee relations.','2026-08-20 17:14:46',0,'active','2026-08-20 17:14:46'),(16,'Strategic Planning','Defining organizational direction and making resource allocation decisions. Covers SWOT analysis, goal setting, KPI development, and long-term visioning.','2026-08-20 17:14:46',0,'active','2026-08-20 17:14:46'),(17,'Inventory Management','Controlling and optimizing stock levels. Covers supply chain coordination, demand forecasting, warehouse operations, and inventory tracking systems.','2026-08-20 17:14:46',0,'active','2026-08-20 17:14:46'),(18,'Compliance & Ethics','Adhering to laws, regulations, and ethical standards. Covers regulatory frameworks, corporate governance, audit processes, and ethical decision-making.','2026-08-20 17:14:46',0,'active','2026-08-20 17:14:46'),(19,'JavaScript','Client-side scripting language for web development','2026-08-22 02:57:23',0,'active','2026-08-22 02:57:23'),(20,'Python','General-purpose programming language','2026-08-22 02:57:23',0,'active','2026-08-22 02:57:23'),(21,'SQL','Structured Query Language for database management','2026-08-22 02:57:23',0,'active','2026-08-22 02:57:23'),(22,'Project Management','Planning, executing, and closing projects','2026-08-22 02:57:23',0,'active','2026-08-22 02:57:23'),(23,'Leadership','Guiding and motivating teams toward goals','2026-08-22 02:57:23',0,'active','2026-08-22 02:57:23'),(24,'Communication','Effective verbal and written communication skills','2026-08-22 02:57:23',0,'active','2026-08-22 02:57:23'),(25,'Data Analysis','Inspecting and modeling data to discover insights','2026-08-22 02:57:23',0,'active','2026-08-22 02:57:23'),(26,'Cybersecurity','Protecting systems from digital attacks','2026-08-22 02:57:23',0,'active','2026-08-22 02:57:23'),(27,'Cloud Computing','Delivering computing services over the internet','2026-08-22 02:57:23',0,'active','2026-08-22 02:57:23'),(28,'Machine Learning','Building systems that learn from data','2026-08-22 02:57:23',0,'active','2026-08-22 02:57:23'),(29,'UX Design','Designing user-friendly digital experiences','2026-08-22 02:57:23',0,'active','2026-08-22 02:57:23'),(30,'Financial Literacy','Understanding financial principles and management','2026-08-22 02:57:23',0,'active','2026-08-22 02:57:23'),(31,'Time Management','Organizing and planning how to divide time','2026-08-22 02:57:23',0,'active','2026-08-22 02:57:23'),(32,'Critical Thinking','Analyzing information to make reasoned judgments','2026-08-22 02:57:23',0,'active','2026-08-22 02:57:23'),(33,'Teamwork','Collaborating effectively with others','2026-08-22 02:57:23',0,'active','2026-08-22 02:57:23'),(34,'Presentation Skills','Delivering engaging and clear presentations','2026-08-22 02:57:23',0,'active','2026-08-22 02:57:23'),(35,'Problem Solving','Finding solutions to complex challenges','2026-08-22 02:57:23',0,'active','2026-08-22 02:57:23'),(36,'Adaptability','Adjusting to new conditions and challenges','2026-08-22 02:57:23',0,'active','2026-08-22 02:57:23');
